#include <ESP32Servo.h>
Servo myServo;
myServo.attach(13);

const float TEMP_THRESHOLD = 30.0;

if (temperature > TEMP_THRESHOLD) {
  myServo.write(90);   // vent open
} else {
  myServo.write(0);    // vent closed
}

float hum  = dht.readHumidity();
float temp = dht.readTemperature();

// isnan() guard, then the [Sensor Scan] line

if (temp > 35.0 || hum > 80.0) {
  myServo.write(180);
  Serial.println("STATUS: CRITICAL HIGH"
                 " - Maximum speed mode");
  Serial.println("Servo Position: 180 degrees");
} else if (temp > 28.0 && hum > 50.0) {
  myServo.write(90);
  Serial.println("STATUS: WARNING MODERATE"
                 " - Standard ventilation mode");
  Serial.println("Servo Position: 90 degrees");
} else {
  myServo.write(0);
  Serial.println("STATUS: SAFE"
                 " - Standby idle mode");
  Serial.println("Servo Position: 0 degrees");
}
